import{_ as a,I as r,c as n,o as t,a3 as o,b as i,w as d,a as s,J as E,a4 as l}from"./chunks/framework.MI-M1z4O.js";const h=JSON.parse('{"title":"SyncAPIM 4-JVMシステムアーキテクチャおよびデータベース設計","description":"SyncAPIMの高性能4-JVMプロセス分離アーキテクチャ（Admin、Receiver、Detector、Gateway）、Redis 7 Streamパイプライン、およびPostgreSQL 18.6ドメインスキーマについて説明します。","frontmatter":{"title":"SyncAPIM 4-JVMシステムアーキテクチャおよびデータベース設計","sidebarTitle":"4-JVMアーキテクチャ・DB設計","description":"SyncAPIMの高性能4-JVMプロセス分離アーキテクチャ（Admin、Receiver、Detector、Gateway）、Redis 7 Streamパイプライン、およびPostgreSQL 18.6ドメインスキーマについて説明します。","head":[["meta",{"name":"keywords","content":"SyncAPIMアーキテクチャ, 4-JVM, sync-apim-admin, sync-apim-receiver, sync-apim-detector, sync-apim-gateway, PostgreSQL 18.6, pg_trgm, wapf_detect_event"}],["meta",{"property":"og:title","content":"SyncAPIM 4-JVMシステムアーキテクチャおよびデータベース設計"}],["meta",{"property":"og:description","content":"超高速パケット収集および脅威検知の負荷分離を実現する4-JVMアーキテクチャとPostgreSQL 18.6単一ストレージ設計"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncapim/architecture"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncapim/architecture"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncapim/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncapim/architecture"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncapim/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncapim/architecture"}]],"sort":2},"headers":[],"relativePath":"ja/syncapim/architecture.md","filePath":"ja/syncapim/architecture.md","lastUpdated":1795293539000}'),A={name:"ja/syncapim/architecture.md"};function p(B,e,g,m,y,f){const c=r("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="syncapim-4-jvmシステムアーキテクチャおよびデータベース設計" tabindex="-1">SyncAPIM 4-JVMシステムアーキテクチャおよびデータベース設計 <a class="header-anchor" href="#syncapim-4-jvmシステムアーキテクチャおよびデータベース設計" aria-label="Permalink to “SyncAPIM 4-JVMシステムアーキテクチャおよびデータベース設計”">​</a></h1><p><code>SyncAPIM</code>は、<strong>Java 25 (Virtual Threads)</strong>、<strong>Spring Boot 4.0</strong>、<strong>AgentScope Java (<code>io.agentscope:agentscope-harness</code>)</strong>、<strong>PostgreSQL 18.6 (<code>JSONB</code> + <code>pg_trgm</code>)</strong>、<strong>Redis 7 Stream</strong>、および<strong>Vue 3 + Vben Admin (<code>@empasy/sync-apim-admin</code>)</strong>の標準技術スタック上に構築された高性能API監視・セキュリティエージェントプラットフォームです。</p><hr><h2 id="_1-パフォーマンス分離型4-jvmプロセスアーキテクチャ" tabindex="-1">1. パフォーマンス分離型4-JVMプロセスアーキテクチャ <a class="header-anchor" href="#_1-パフォーマンス分離型4-jvmプロセスアーキテクチャ" aria-label="Permalink to “1. パフォーマンス分離型4-JVMプロセスアーキテクチャ”">​</a></h2><p>大規模APIトラフィック環境において、パケット収集（I/O集約型）と正規表現・JWT脅威検知（CPU集約型）の負荷が管理コンソールやインラインゲートウェイの応答遅延に影響を与えないよう、<strong>4つの独立したJVMプロセス</strong>に分離して起動します。</p>',5)),(t(),i(l,null,{default:d(()=>[E(c,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20TrafficSources%20%5B%22%E4%BF%9D%E8%AD%B7%E5%AF%BE%E8%B1%A1API%E3%83%9B%E3%82%B9%E3%83%88%E3%83%BB%E5%8F%8E%E9%9B%86%E3%82%A8%E3%83%BC%E3%82%B8%E3%82%A7%E3%83%B3%E3%83%88%22%5D%0A%20%20%20%20%20%20%20%20Beat%5B%22Packetbeat%20%2F%20Filebeat%3Cbr%2F%3E(TCP%205044%20%2F%205055)%22%5D%0A%20%20%20%20%20%20%20%20Client%5B%22API%E3%82%AF%E3%83%A9%E3%82%A4%E3%82%A2%E3%83%B3%E3%83%88%E3%83%AA%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88%3Cbr%2F%3E(HTTP%2FHTTPS)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SyncApimCluster%20%5B%22SyncAPIM%204-JVM%E7%8B%AC%E7%AB%8B%E3%83%97%E3%83%AD%E3%82%BB%E3%82%B9%E3%82%AF%E3%83%A9%E3%82%B9%E3%82%BF%E3%83%BC%22%5D%0A%20%20%20%20%20%20%20%20GW%5B%22JVM%20%234%3A%20sync-apim-gateway%20(18091)%3Cbr%2F%3E%E5%8B%95%E7%9A%84BlockedApiFilter%E3%83%BB%E3%83%88%E3%83%A9%E3%83%95%E3%82%A3%E3%83%83%E3%82%AF%E3%83%9F%E3%83%A9%E3%83%BC%E3%83%AA%E3%83%B3%E3%82%B0%22%5D%0A%20%20%20%20%20%20%20%20RCV%5B%22JVM%20%232%3A%20sync-apim-receiver%20(18090)%3Cbr%2F%3EVirtual%20Thread%E3%83%91%E3%82%B1%E3%83%83%E3%83%88%E3%83%AB%E3%83%BC%E3%82%BF%E3%83%BC%E3%83%BB%E5%8F%8E%E9%9B%86API%22%5D%0A%20%20%20%20%20%20%20%20DET%5B%22JVM%20%233%3A%20sync-apim-detector%20(18092)%3Cbr%2F%3EOpenAPI%203.0%E6%8E%A8%E8%AB%96%E3%83%BBWAF%E3%83%AB%E3%83%BC%E3%83%AB%E3%83%9E%E3%83%83%E3%83%81%E3%83%B3%E3%82%B0%E3%83%BBPII%E3%83%9E%E3%82%B9%E3%82%AD%E3%83%B3%E3%82%B0%22%5D%0A%20%20%20%20%20%20%20%20ADM%5B%22JVM%20%231%3A%20sync-apim-admin%20(18089)%3Cbr%2F%3E%E7%B5%B1%E5%90%88%E7%9B%A3%E8%A6%96API%E3%83%BB%E7%B5%B1%E8%A8%88%E3%83%90%E3%83%83%E3%83%81%E3%83%BBMCP%E3%82%B5%E3%83%BC%E3%83%90%E3%83%BC%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Storage%20%5B%22%E5%85%A8%E7%A4%BE%E5%8D%98%E4%B8%80%E3%83%87%E3%83%BC%E3%82%BF%E3%83%97%E3%83%AC%E3%83%BC%E3%83%B3%22%5D%0A%20%20%20%20%20%20%20%20Redis%5B(%22Redis%207%3Cbr%2F%3EStream%3A%20job_queue%3Cbr%2F%3ECache%3A%20wapf%3Apolicy%3Arules%20%2F%20blocked%3Aendpoints%22)%5D%0A%20%20%20%20%20%20%20%20PG%5B(%22PostgreSQL%2018.6%20(sync_apim)%3Cbr%2F%3Ewapf_*%2017%E3%83%86%E3%83%BC%E3%83%96%E3%83%AB%20%2B%20pg_trgm%20GIN%E3%82%A4%E3%83%B3%E3%83%87%E3%83%83%E3%82%AF%E3%82%B9%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20Client%20--%3E%20GW%0A%20%20%20%20Beat%20--%3E%20RCV%0A%20%20%20%20GW%20--%3E%7C%E9%9D%9E%E5%90%8C%E6%9C%9F%E3%83%88%E3%83%A9%E3%83%95%E3%82%A3%E3%83%83%E3%82%AF%E3%83%9F%E3%83%A9%E3%83%BC%E3%83%AA%E3%83%B3%E3%82%B0%7C%20RCV%0A%20%20%20%20RCV%20--%3E%7CXADD%20job_queue%7C%20Redis%0A%20%20%20%20Redis%20--%3E%7CXREADGROUP%7C%20DET%0A%20%20%20%20DET%20--%3E%7C%E3%82%A8%E3%83%B3%E3%83%89%E3%83%9D%E3%82%A4%E3%83%B3%E3%83%88%E3%83%BB%E4%BB%95%E6%A7%98%E3%83%BB%E6%A4%9C%E7%9F%A5%E3%82%A4%E3%83%99%E3%83%B3%E3%83%88%E4%BF%9D%E5%AD%98%7C%20PG%0A%20%20%20%20ADM%20%3C--%3E%7C%E3%82%AB%E3%82%BF%E3%83%AD%E3%82%B0%E3%83%BB%E3%83%9D%E3%83%AA%E3%82%B7%E3%83%BC%E3%83%BB%E7%B5%B1%E8%A8%88%E3%83%BB%E3%83%89%E3%83%AA%E3%83%95%E3%83%88%E7%9B%A3%E6%9F%BB%7C%20PG%0A%20%20%20%20ADM%20--%3E%7C%22%E3%83%9D%E3%83%AA%E3%82%B7%E3%83%BC%2F%E6%A9%9F%E5%AF%86%E6%83%85%E5%A0%B1%2F%E9%81%AE%E6%96%AD%E3%83%AA%E3%82%B9%E3%83%88%E3%81%AE%E3%83%AA%E3%82%A2%E3%83%AB%E3%82%BF%E3%82%A4%E3%83%A0%E5%90%8C%E6%9C%9F%22%7C%20Redis%0A%20%20%20%20Redis%20--%3E%7C%E9%81%AE%E6%96%AD%E3%83%91%E3%82%B9%E3%81%8A%E3%82%88%E3%81%B3%E6%A4%9C%E7%9F%A5%E3%83%AB%E3%83%BC%E3%83%AB%E3%81%AE%E5%8D%B3%E6%99%82%E5%8F%8D%E6%98%A0%7C%20GW%0A%20%20%20%20Redis%20--%3E%7C%E6%A4%9C%E7%9F%A5%E3%83%AB%E3%83%BC%E3%83%AB%E3%81%8A%E3%82%88%E3%81%B3PII%E3%83%91%E3%82%BF%E3%83%BC%E3%83%B3%E3%82%AD%E3%83%A3%E3%83%83%E3%82%B7%E3%83%A5%E5%8F%82%E7%85%A7%7C%20DET%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-jvm別役割およびポート規格" tabindex="-1">1.1 JVM別役割およびポート規格 <a class="header-anchor" href="#_1-1-jvm別役割およびポート規格" aria-label="Permalink to “1.1 JVM別役割およびポート規格”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">JVMモジュール名</th><th style="text-align:center;">ホストポート（コンテナ）</th><th style="text-align:left;">コアクラス</th><th style="text-align:left;">主な役割およびパフォーマンス分離の目的</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>sync-apim-admin</code></strong></td><td style="text-align:center;"><code>18089</code> (<code>8080</code>)</td><td style="text-align:left;"><code>WapfApiEndPointController</code>, <code>WapfPolicyController</code>, <code>ApimTrafficAggregationService</code>, <code>SyncApimAgent</code>, <code>ApimMcpController</code></td><td style="text-align:left;">11の管理画面用REST API（<code>/api/v1/apim/...</code>）、5分間隔のトラフィック・脅威統計集計バッチ、<code>SyncVerse</code>連携用6大MCPツールの提供</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-receiver</code></strong></td><td style="text-align:center;"><code>18090</code> (<code>8081</code>)<br>TCP <code>5044</code>/<code>5055</code></td><td style="text-align:left;"><code>PacketReceiver</code>, <code>LumberjackRouter</code>, <code>RedisStreamProducerService</code>, <code>ApimReceiverController</code></td><td style="text-align:left;">Java 25 Virtual ThreadsベースのノンブロッキングTCPソケットサーバーおよびHTTP収集エンドポイント（<code>/api/v1/apim/receiver/ingest</code>）の運用、Redis Stream <code>job_queue</code>への格納</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-detector</code></strong></td><td style="text-align:center;"><code>18092</code> (<code>8090</code>)</td><td style="text-align:left;"><code>RedisStreamConsumer</code>, <code>DetectionRuleServiceImpl</code>, <code>WapfDetectRuleServiceImpl</code></td><td style="text-align:left;">Redis Streamワーカースレッドプールでのリアルタイムパケット解析、エンドポイント自動登録、OpenAPI 3.0.1仕様合成、6大WAF正規表現/JWT脅威検知および8大PIIマスキング後のPostgreSQL <code>wapf_detect_event</code>への保存</td></tr><tr><td style="text-align:left;"><strong><code>sync-apim-gateway</code></strong></td><td style="text-align:center;"><code>18091</code> (<code>8083</code>)</td><td style="text-align:left;"><code>BlockedApiFilter</code>, <code>BlockedApiRegistryService</code>, <code>ApimGatewayController</code></td><td style="text-align:left;">DB（<code>wapf_api_endpoint.block_status=&#39;1&#39;</code>）およびRedis（<code>wapf:blocked:endpoints</code>）と同期し、遮断対象のシャドー/高リスクAPI呼び出しを<code>403 Forbidden</code>で即時遮断して正常トラフィックを<code>receiver</code>へミラーリング</td></tr></tbody></table><hr><h2 id="_2-マルチモジュールディレクトリおよびmaven座標構造" tabindex="-1">2. マルチモジュールディレクトリおよびMaven座標構造 <a class="header-anchor" href="#_2-マルチモジュールディレクトリおよびmaven座標構造" aria-label="Permalink to “2. マルチモジュールディレクトリおよびMaven座標構造”">​</a></h2><p><code>sync-apim/Server/</code>配下のすべてのモジュールは、全社標準に従い<code>artifactId</code>と物理ディレクトリ名が<code>1:1</code>で一致しています。</p><ul><li><strong>最上位親POM</strong>: <code>com.empasy.sync.apim:sync-apim-parent:1.0.0-SNAPSHOT</code> (<code>sync-apim/pom.xml</code>)</li><li><strong>バックエンド親POM</strong>: <code>com.empasy.sync.apim:sync-apim-server-parent:1.0.0-SNAPSHOT</code> (<code>sync-apim/Server/pom.xml</code>)</li><li><strong>共通およびコアモジュール</strong>: <ul><li><code>Server/sync-apim-common</code>: 17のドメインエンティティ（<code>WapfApiEndPoint</code>、<code>WapfDetectEvent</code>等）、MyBatis-Plus Mapper、共通Service（<code>WapfOpenApiSpecServiceImpl</code>ドリフト監査エンジンを含む）</li><li><code>Server/sync-apim-base-core</code>: <code>MybatisPlusConfig</code>、<code>RedisConfig</code>、<code>AuthInterceptor</code>、<code>GlobalExceptionHandler</code></li><li><code>Server/sync-apim-module-system</code>: システム認証・認可およびDB動的メニュー供給（<code>/api/v1/apim/sys/permission/getUserPermissionByToken</code>）</li></ul></li></ul><hr><h2 id="_3-postgresql-18-6ドメインデータベース設計-db-02-schema-domain-sql" tabindex="-1">3. PostgreSQL 18.6ドメインデータベース設計 (<code>db/02_schema_domain.sql</code>) <a class="header-anchor" href="#_3-postgresql-18-6ドメインデータベース設計-db-02-schema-domain-sql" aria-label="Permalink to “3. PostgreSQL 18.6ドメインデータベース設計 (db/02_schema_domain.sql)”">​</a></h2><p>従来のPostgreSQL 18.6 / PostgreSQL 18.6 + OpenSearchの二重ストレージを単一の<strong>PostgreSQL 18.6（<code>sync_apim</code>データベース）</strong>に統合することで、運用の複雑さとメモリ占有率を低減しました。</p><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">物理テーブル名</th><th style="text-align:left;">主なカラムおよび設計上の特徴</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>エージェント・ホスト</strong></td><td style="text-align:left;"><code>wapf_agent</code>, <code>wapf_agent_host</code>, <code>wapf_host</code></td><td style="text-align:left;">収集エージェントマスター（SHA-256 <code>auth_key</code>）、保護対象APIホスト（<code>host</code>, <code>status</code>）および<code>N:M</code>マッピング</td></tr><tr><td style="text-align:left;"><strong>APIカタログ</strong></td><td style="text-align:left;"><code>wapf_api_endpoint</code>, <code>wapf_api_endpoint_detail</code>, <code>wapf_api_endpoint_history</code></td><td style="text-align:left;">自動検出された<code>host</code> + <code>path</code> + <code>method</code>の固有エンドポイント、リスクスコア（<code>risk_score</code>）、遮断状態（<code>block_status</code>）、パスマージ履歴</td></tr><tr><td style="text-align:left;"><strong>データフィールド・仕様</strong></td><td style="text-align:left;"><code>wapf_data_field</code>, <code>wapf_open_api_spec</code></td><td style="text-align:left;">リクエスト/レスポンスセクション別（<code>REQ_QUERY</code>, <code>REQ_BODY</code>, <code>RES_BODY</code>）のJSONPathフィールド、機密情報マッピング（<code>sensitivity_uuid</code>）、OpenAPI 3.0.1 JSON仕様およびドリフト状態（<code>contract_status</code>, <code>drift_summary</code>）</td></tr><tr><td style="text-align:left;"><strong>WAFポリシー・検知ルール</strong></td><td style="text-align:left;"><code>wapf_policy</code>, <code>wapf_policy_api_endpoint</code>, <code>wapf_policy_rule</code>, <code>wapf_rule</code></td><td style="text-align:left;">7大セキュリティポリシーマスター（<code>basic</code>デフォルトポリシー有無）、ポリシー別エンドポイント適用マッピング、6大脅威検知正規表現（<code>pattern</code>）およびJWT検証オプション（<code>jwt_option</code>）</td></tr><tr><td style="text-align:left;"><strong>機密情報・アラート</strong></td><td style="text-align:left;"><code>wapf_sensitivity</code>, <code>wapf_email</code></td><td style="text-align:left;">8大個人・金融機密情報検知正規表現マスター、高リスク脅威発生時のセキュリティ担当者への警告メール送信履歴</td></tr><tr><td style="text-align:left;"><strong>時系列統計</strong></td><td style="text-align:left;"><code>wapf_endpoint_average</code>, <code>wapf_rule_average</code></td><td style="text-align:left;">エンドポイント別の呼び出し数および脅威検知ルール別・深刻度別の時系列集計テーブル</td></tr><tr><td style="text-align:left;"><strong>リアルタイム検知イベント</strong></td><td style="text-align:left;"><code>wapf_detect_event</code></td><td style="text-align:left;">パケットのリクエスト/レスポンスヘッダー・パラメーター・本文（<code>JSONB</code>およびマスキング済みテキスト）、脅威コード配列（<code>threat_codes</code>）、リスクスコア、<code>pg_trgm</code> GINインデックスベースの超高速全文検索</td></tr></tbody></table>',10))])}const C=a(A,[["render",p]]);export{h as __pageData,C as default};
